from pathlib import Path


VIEWER_MODEL_API = "https://sketchfab.com/i/models"
USER_AGENT = "load-sketchfab-threejs/1.0"


def model_uid(value: str) -> str:
    match = re.search(r"[a-f0-9]{32}", value)
