@media (orientation: landscape) and (max-height: 520px) {
  #rotate-hint {
    position: fixed;
    inset: auto 0 12px;
    display: block;
    text-align: center;
    font-size: 11px;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.45);
    pointer-events: none;
  }
}

const NOTE = (midi) => 440 * 2 ** ((midi - 69) / 12);

const CHORDS = [
  { notes: [60, 64, 67, 71], bass: 48, pad: [48, 55, 64] },
  { notes: [57, 60, 64, 67], bass: 45, pad: [45, 52, 60] },
  { notes: [53, 57, 60, 64], bass: 41, pad: [41, 48, 57] },
  { notes: [55, 59, 62, 67], bass: 43, pad: [43, 50, 59] },
];

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.noise = null;
    this.nextNote = 0;
    this.step = 0;
    this.timer = null;
    this.muted = false;
    this.started = false;
  }

  ensure() {
    if (this.ctx) {
      if (this.ctx.state === "suspended") this.ctx.resume();
      return this.ctx;
    }
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return null;
    this.ctx = new AudioCtx();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.75;
    this.master.connect(this.ctx.destination);

    const compressor = this.ctx.createDynamicsCompressor();
    compressor.threshold.value = -18;
    compressor.knee.value = 18;
    compressor.ratio.value = 4;
    compressor.connect(this.master);

    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = 0.19;
    this.musicGain.connect(compressor);

    this.sfxGain = this.ctx.createGain();
    this.sfxGain.gain.value = 0.42;
    this.sfxGain.connect(compressor);

    const buffer = this.ctx.createBuffer(1, this.ctx.sampleRate * 1.2, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < data.length; i += 1) data[i] = Math.random() * 2 - 1;
    this.noise = buffer;

    return this.ctx;
  }

  init() {
    if (!this.ensure() || this.started) return;
    this.started = true;
    this.nextNote = this.ctx.currentTime + 0.1;
    this.timer = window.setInterval(() => this.scheduleMusic(), 120);
    this.scheduleMusic();
  }

  setMuted(muted) {
    this.muted = muted;
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    this.master.gain.cancelScheduledValues(now);
    this.master.gain.setTargetAtTime(muted ? 0 : 0.75, now, 0.08);
  }

  scheduleMusic() {
    if (!this.ctx || this.muted) return;
    const horizon = this.ctx.currentTime + 0.8;
    while (this.nextNote < horizon) {
      this.playStep(this.step, this.nextNote);
      this.step += 1;
      this.nextNote += 0.25;
    }
  }

  playStep(step, time) {
    const bar = Math.floor(step / 8) % CHORDS.length;
    const beat = step % 8;
    const chord = CHORDS[bar];
    if (beat === 0) {
      chord.pad.forEach((midi, index) => {
        this.tone(NOTE(midi), time + index * 0.015, 1.9, 0.022, "sine", this.musicGain, 1.8);
      });
      this.tone(NOTE(chord.bass), time, 1.6, 0.06, "triangle", this.musicGain, 0.8);
    }

    const pattern = [0, 2, 1, 3, 2, 1, 3, 2];
    const note = chord.notes[pattern[beat]];
    const velocity = beat === 0 ? 0.07 : 0.045;
    this.tone(NOTE(note + 12), time, 0.55, velocity, "triangle", this.musicGain, 2.6, 0.5);
    if (beat === 4 || beat === 6) {
      const sparkle = chord.notes[(beat + bar) % chord.notes.length] + 24;
      this.tone(NOTE(sparkle), time + 0.04, 0.4, 0.015, "sine", this.musicGain, 3.2);
    }
  }

  tone(freq, time, duration, volume, type, destination, attack = 0.01, detune = 0) {
    if (!this.ctx) return;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.value = freq;
    osc.detune.value = detune;
    gain.gain.setValueAtTime(0.0001, time);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, volume), time + Math.min(attack, duration * 0.25));
    gain.gain.exponentialRampToValueAtTime(0.0001, time + duration);
    osc.connect(gain);
    gain.connect(destination);
    osc.start(time);
    osc.stop(time + duration + 0.05);
  }

  noiseBurst(time, duration, volume, filterFreq, destination) {
    if (!this.ctx || !this.noise) return;
    const source = this.ctx.createBufferSource();
    source.buffer = this.noise;
    const filter = this.ctx.createBiquadFilter();
    filter.type = "bandpass";
    filter.frequency.value = filterFreq;
    filter.Q.value = 0.9;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(volume, time);
    gain.gain.exponentialRampToValueAtTime(0.0001, time + duration);
    source.connect(filter);
    filter.connect(gain);
    gain.connect(destination || this.sfxGain);
    source.start(time);
    source.stop(time + duration + 0.02);
  }

  sweep(from, to, time, duration, volume, type = "sine") {
    if (!this.ctx) return;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(from, time);
    osc.frequency.exponentialRampToValueAtTime(Math.max(20, to), time + duration);
    gain.gain.setValueAtTime(0.0001, time);
    gain.gain.exponentialRampToValueAtTime(volume, time + 0.01);
    gain.gain.exponentialRampToValueAtTime(0.0001, time + duration);
    osc.connect(gain);
    gain.connect(this.sfxGain);
    osc.start(time);
    osc.stop(time + duration + 0.03);
  }

  sfx(name) {
    if (!this.ensure() || this.muted) return;
    const now = this.ctx.currentTime + 0.01;
    switch (name) {
      case "click":
        this.tone(620, now, 0.08, 0.06, "triangle", this.sfxGain);
        break;
      case "place":
        this.sweep(220, 520, now, 0.13, 0.17, "sine");
        this.sweep(440, 780, now + 0.05, 0.14, 0.08, "triangle");
        break;
      case "deny":
        this.tone(180, now, 0.12, 0.12, "square", this.sfxGain);
        this.tone(145, now + 0.08, 0.14, 0.1, "square", this.sfxGain);
        break;
      case "pop":
        this.noiseBurst(now, 0.09, 0.18, 1700);
        this.sweep(300, 80, now, 0.12, 0.14, "triangle");
        break;
      case "laser":
        this.sweep(1300, 420, now, 0.08, 0.07, "square");
        break;
      case "star":
        this.tone(NOTE(84), now, 0.24, 0.12, "sine", this.sfxGain);
        this.tone(NOTE(91), now + 0.07, 0.3, 0.09, "sine", this.sfxGain);
        break;
      case "heal":
        this.tone(NOTE(76), now, 0.25, 0.08, "sine", this.sfxGain);
        this.tone(NOTE(83), now + 0.09, 0.35, 0.06, "triangle", this.sfxGain);
        break;
      case "hurt":
        this.sweep(180, 70, now, 0.22, 0.16, "sawtooth");
        this.noiseBurst(now, 0.15, 0.12, 400);
        break;
      case "wave":
        [60, 67, 72].forEach((midi, index) => {
          this.tone(NOTE(midi), now + index * 0.09, 0.5, 0.1, "triangle", this.sfxGain);
        });
        break;
      case "power":
        [60, 64, 67, 72, 76].forEach((midi, index) => {
          this.tone(NOTE(midi + 12), now + index * 0.06, 0.65, 0.09, "sine", this.sfxGain);
        });
        this.noiseBurst(now, 0.55, 0.16, 2400);
        break;
      case "victory":
        [60, 64, 67, 72, 76, 79].forEach((midi, index) => {
          this.tone(NOTE(midi + 12), now + index * 0.12, 0.9, 0.12, "triangle", this.sfxGain);
        });
        break;
      case "defeat":
        [64, 60, 57, 52].forEach((midi, index) => {
          this.tone(NOTE(midi), now + index * 0.18, 0.65, 0.1, "sine", this.sfxGain);
        });
        break;
      case "claim":
        [72, 76, 79, 84].forEach((midi, index) => {
          this.tone(NOTE(midi), now + index * 0.07, 0.4, 0.08, "sine", this.sfxGain);
        });
        break;
      default:
        break;
    }
  }
}

import { COLORS, GRID, UNITS, UNIT_BY_ID } from "./data.js";

const INK = COLORS.ink;
let paperPattern = null;

export function setFont(ctx, size, weight = 700, family = '"Baloo 2", sans-serif') {
  ctx.font = `${weight} ${size}px ${family}`;
}

export function text(ctx, value, x, y, size, color = COLORS.cream, options = {}) {
  const {
    align = "center",
    baseline = "middle",
    weight = 700,
    family = '"Baloo 2", sans-serif',
    stroke = 0,
    strokeColor = INK,
    alpha = 1,
    shadow = null,
    letterSpacing = 0,
  } = options;
  ctx.save();
  ctx.globalAlpha *= alpha;
  setFont(ctx, size, weight, family);
  ctx.textAlign = align;
  ctx.textBaseline = baseline;
  ctx.lineJoin = "round";
  if (letterSpacing && "letterSpacing" in ctx) ctx.letterSpacing = `${letterSpacing}px`;
  if (shadow) {
    ctx.fillStyle = shadow;
    ctx.fillText(value, x + 2, y + 3);
  }
  if (stroke > 0) {
    ctx.lineWidth = stroke;
    ctx.strokeStyle = strokeColor;
    ctx.strokeText(value, x, y);
  }
  ctx.fillStyle = color;
  ctx.fillText(value, x, y);
  ctx.restore();
}

export function roundRectPath(ctx, x, y, w, h, r = 10) {
  const radius = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.lineTo(x + w - radius, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + radius);
  ctx.lineTo(x + w, y + h - radius);
  ctx.quadraticCurveTo(x + w, y + h, x + w - radius, y + h);
  ctx.lineTo(x + radius, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - radius);
  ctx.lineTo(x, y + radius);
  ctx.quadraticCurveTo(x, y, x + radius, y);
  ctx.closePath();
}

export function ellipsePath(ctx, x, y, rx, ry) {
  ctx.beginPath();
  ctx.ellipse(x, y, Math.max(0.1, rx), Math.max(0.1, ry), 0, 0, Math.PI * 2);
}

export function drawStar(ctx, x, y, outer, inner = outer * 0.46, points = 5, rotation = -Math.PI / 2) {
  ctx.beginPath();
  for (let i = 0; i < points * 2; i += 1) {
    const radius = i % 2 === 0 ? outer : inner;
    const angle = rotation + (i * Math.PI) / points;
    const px = x + Math.cos(angle) * radius;
    const py = y + Math.sin(angle) * radius;
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
}

export function drawHeart(ctx, x, y, size) {
  ctx.beginPath();
  ctx.moveTo(x, y + size * 0.72);
  ctx.bezierCurveTo(x - size * 1.1, y + size * 0.05, x - size * 0.8, y - size * 0.85, x, y - size * 0.32);
  ctx.bezierCurveTo(x + size * 0.8, y - size * 0.85, x + size * 1.1, y + size * 0.05, x, y + size * 0.72);
  ctx.closePath();
}

export function outlined(ctx, fill, stroke = INK, width = 3, pathFn = null) {
  if (pathFn) pathFn();
  if (fill) {
    ctx.fillStyle = fill;
    ctx.fill();
  }
  if (stroke) {
    ctx.lineWidth = width;
    ctx.strokeStyle = stroke;
    ctx.lineJoin = "round";
    ctx.lineCap = "round";
    ctx.stroke();
  }
}

export function line(ctx, x1, y1, x2, y2, color = INK, width = 3) {
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.lineCap = "round";
  ctx.stroke();
}

export function drawPaperTexture(ctx, x, y, w, h, alpha = 0.45) {
  if (!paperPattern) {
    const tile = document.createElement("canvas");
    tile.width = 256;
    tile.height = 256;
    const tctx = tile.getContext("2d");
    for (let i = 0; i < 620; i += 1) {
      const px = Math.random() * 256;
      const py = Math.random() * 256;
      const light = Math.random() > 0.48;
      tctx.fillStyle = light ? `rgba(255,255,255,${Math.random() * 0.09})` : `rgba(0,0,0,${Math.random() * 0.1})`;
      tctx.fillRect(px, py, Math.random() > 0.8 ? 2 : 1, 1);
    }
    tctx.lineWidth = 0.6;
    for (let i = 0; i < 55; i += 1) {
      tctx.strokeStyle = `rgba(255,255,255,${0.015 + Math.random() * 0.04})`;
      tctx.beginPath();
      const sx = Math.random() * 256;
      const sy = Math.random() * 256;
      tctx.moveTo(sx, sy);
      tctx.quadraticCurveTo(sx + 12, sy + Math.random() * 6 - 3, sx + 20 + Math.random() * 30, sy + Math.random() * 6 - 3);
      tctx.stroke();
    }
    paperPattern = ctx.createPattern(tile, "repeat");
  }
  ctx.save();
  ctx.globalAlpha *= alpha;
  ctx.fillStyle = paperPattern;
  ctx.fillRect(x, y, w, h);
  ctx.restore();
}

function shadow(ctx, x, y, rx, ry, alpha = 0.32) {
  ctx.save();
  ctx.globalAlpha *= alpha;
  ctx.fillStyle = "#090815";
  ellipsePath(ctx, x, y, rx, ry);
  ctx.fill();
  ctx.restore();
}

function glow(ctx, x, y, radius, color, alpha = 0.35) {
  const grad = ctx.createRadialGradient(x, y, 0, x, y, radius);
  grad.addColorStop(0, color);
  grad.addColorStop(1, "rgba(0,0,0,0)");
  ctx.save();
  ctx.globalAlpha *= alpha;
  ctx.fillStyle = grad;
  ctx.fillRect(x - radius, y - radius, radius * 2, radius * 2);
  ctx.restore();
}

function eye(ctx, x, y, r = 2.5, pupil = INK, shine = true) {
  ctx.fillStyle = INK;
  ellipsePath(ctx, x, y, r, r * 1.15);
  ctx.fill();
  if (shine) {
    ctx.fillStyle = "#ffffff";
    ellipsePath(ctx, x - r * 0.32, y - r * 0.38, r * 0.34, r * 0.34);
    ctx.fill();
  }
}

function blush(ctx, x, y, color = "rgba(255,120,150,0.55)") {
  ctx.fillStyle = color;
  ellipsePath(ctx, x, y, 4.2, 2.4);
  ctx.fill();
}

/* ------------------------------------------------------------------ icons */

export function drawMoonIcon(ctx, x, y, size, color = COLORS.gold) {
  ctx.save();
  ctx.translate(x, y);
  ctx.beginPath();
  ctx.arc(0, 0, size, Math.PI * 0.38, Math.PI * 1.62, false);
  ctx.arc(size * 0.42, 0, size * 0.84, Math.PI * 1.54, Math.PI * 0.46, true);
  ctx.closePath();
  ctx.fillStyle = color;
  ctx.fill();
  ctx.strokeStyle = INK;
  ctx.lineWidth = Math.max(1.5, size * 0.16);
  ctx.stroke();
  ctx.restore();
}

export function drawGemIcon(ctx, x, y, size) {
  ctx.save();
  ctx.translate(x, y);
  ctx.beginPath();
  ctx.moveTo(0, -size);
  ctx.lineTo(size * 0.9, -size * 0.22);
  ctx.lineTo(size * 0.5, size * 0.85);
  ctx.lineTo(-size * 0.5, size * 0.85);
  ctx.lineTo(-size * 0.9, -size * 0.22);
  ctx.closePath();
  const grad = ctx.createLinearGradient(0, -size, 0, size);
  grad.addColorStop(0, "#b6f5ff");
  grad.addColorStop(0.45, COLORS.cyan);
  grad.addColorStop(1, "#148ac9");
  ctx.fillStyle = grad;
  ctx.fill();
  ctx.lineWidth = 2;
  ctx.strokeStyle = INK;
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(-size * 0.9, -size * 0.22);
  ctx.lineTo(size * 0.9, -size * 0.22);
  ctx.moveTo(0, -size);
  ctx.lineTo(-size * 0.35, size * 0.85);
  ctx.moveTo(0, -size);
  ctx.lineTo(size * 0.35, size * 0.85);
  ctx.strokeStyle = "rgba(255,255,255,0.35)";
  ctx.lineWidth = 1.2;
  ctx.stroke();
  ctx.restore();
}

export function drawLock(ctx, x, y, size, color = COLORS.gold) {
  ctx.save();
  ctx.translate(x, y);
  ctx.beginPath();
  ctx.arc(0, -size * 0.18, size * 0.48, Math.PI, 0);
  ctx.strokeStyle = color;
  ctx.lineWidth = size * 0.24;
  ctx.stroke();
  roundRectPath(ctx, -size * 0.62, -size * 0.1, size * 1.24, size * 0.95, size * 0.22);
  ctx.fillStyle = color;
  ctx.fill();
  ctx.lineWidth = 2;
  ctx.strokeStyle = INK;
  ctx.stroke();
  ctx.fillStyle = INK;
  ctx.beginPath();
  ctx.arc(0, size * 0.24, size * 0.13, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillRect(-size * 0.07, size * 0.26, size * 0.14, size * 0.28);
  ctx.restore();
}

export function drawSoundIcon(ctx, x, y, size, muted, color = COLORS.cream) {
  ctx.save();
  ctx.translate(x, y);
  ctx.beginPath();
  ctx.moveTo(-size * 0.7, -size * 0.25);
  ctx.lineTo(-size * 0.32, -size * 0.25);
  ctx.lineTo(size * 0.12, -size * 0.65);
  ctx.lineTo(size * 0.12, size * 0.65);
  ctx.lineTo(-size * 0.32, size * 0.25);
  ctx.lineTo(-size * 0.7, size * 0.25);
  ctx.closePath();
  ctx.fillStyle = color;
  ctx.fill();
  ctx.lineWidth = 1.8;
  ctx.strokeStyle = INK;
  ctx.stroke();
  if (muted) {
    line(ctx, size * 0.35, -size * 0.3, size * 0.78, size * 0.3, COLORS.coral, 2.4);
    line(ctx, size * 0.78, -size * 0.3, size * 0.35, size * 0.3, COLORS.coral, 2.4);
  } else {
    ctx.beginPath();
    ctx.arc(0, 0, size * 0.55, -0.8, 0.8);
    ctx.strokeStyle = color;
    ctx.lineWidth = 1.8;
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(0, 0, size * 0.85, -0.65, 0.65);
    ctx.strokeStyle = color;
    ctx.lineWidth = 1.5;
    ctx.globalAlpha *= 0.6;
    ctx.stroke();
  }
  ctx.restore();
}

export function drawStarCoin(ctx, x, y, size, time = 0) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(Math.sin(time * 2.2) * 0.08);
  const grad = ctx.createLinearGradient(0, -size, 0, size);
  grad.addColorStop(0, "#fff7a1");
  grad.addColorStop(0.55, COLORS.gold);
  grad.addColorStop(1, "#f3a400");
  drawStar(ctx, 0, 0, size, size * 0.47, 5);
  ctx.fillStyle = grad;
  ctx.fill();
  ctx.lineWidth = Math.max(1.8, size * 0.17);
  ctx.strokeStyle = INK;
  ctx.lineJoin = "round";
  ctx.stroke();
  ctx.fillStyle = "rgba(255,255,255,0.6)";
  ellipsePath(ctx, -size * 0.25, -size * 0.3, size * 0.15, size * 0.1);
  ctx.fill();
  ctx.restore();
}

export function drawSwordIcon(ctx, x, y, size, color = COLORS.cyan) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(-Math.PI / 4);
  roundRectPath(ctx, -size * 0.09, -size * 0.85, size * 0.18, size * 1.1, size * 0.09);
  ctx.fillStyle = color;
  ctx.fill();
  ctx.lineWidth = 1.6;
  ctx.strokeStyle = INK;
  ctx.stroke();
  roundRectPath(ctx, -size * 0.45, size * 0.15, size * 0.9, size * 0.16, size * 0.08);
  ctx.fillStyle = COLORS.gold;
  ctx.fill();
  ctx.stroke();
  roundRectPath(ctx, -size * 0.1, size * 0.25, size * 0.2, size * 0.45, size * 0.08);
  ctx.fillStyle = "#9a5a3c";
  ctx.fill();
  ctx.stroke();
  ctx.restore();
}

/* -------------------------------------------------------------- characters */

function toyFace(ctx, x, y, scale = 1) {
  eye(ctx, x - 5 * scale, y, 2.4 * scale);
  eye(ctx, x + 5 * scale, y, 2.4 * scale);
  blush(ctx, x - 10 * scale, y + 5 * scale);
  blush(ctx, x + 10 * scale, y + 5 * scale);
}

function drawTeddy(ctx, time, attack, hurt) {
  const bob = Math.sin(time * 3.1) * 1.2;
  shadow(ctx, 0, 30, 23, 6);
  ctx.translate(0, bob);

  // legs
  outlined(ctx, "#b9783f", INK, 3, () => {
    ellipsePath(ctx, -12, 22, 9, 8);
  });
  outlined(ctx, "#b9783f", INK, 3, () => {
    ellipsePath(ctx, 12, 22, 9, 8);
  });

  // sword arm group
  ctx.save();
  ctx.translate(17, -1);
  ctx.rotate(-0.5 + attack * 1.25);
  line(ctx, 0, 0, 12, -19, INK, 7);
  line(ctx, 0, 0, 12, -19, "#d99655", 4);
  outlined(ctx, "#e8f8ff", INK, 2.5, () => {
    ctx.beginPath();
    ctx.moveTo(9, -16);
    ctx.lineTo(13, -33);
    ctx.lineTo(17, -16);
    ctx.lineTo(16, -13);
    ctx.lineTo(10, -13);
    ctx.closePath();
  });
  line(ctx, 8, -14, 18, -14, COLORS.gold, 4);
  ctx.restore();

  // body
  const bodyGrad = ctx.createLinearGradient(-18, -8, 18, 28);
  bodyGrad.addColorStop(0, "#e5aa6d");
  bodyGrad.addColorStop(1, "#c48147");
  outlined(ctx, bodyGrad, INK, 3.2, () => {
