    ctx.quadraticCurveTo(18, -25, 30, -14);
    ctx.quadraticCurveTo(24, -10, 26, -2);
    ctx.quadraticCurveTo(19, -4, 17, 3);
    ctx.quadraticCurveTo(11, 0, 5, 4);
