  drawStatTile(ctx, 64, 305, 108, 56, "DREAM LEFT", `${stats.dream}`, "#55d98b");
  drawStatTile(ctx, 186, 305, 108, 56, "BANISHED", `${stats.kills}`, "#ffd700");
  drawStatTile(ctx, 308, 305, 108, 56, "STARS", `${stats.stars}`, "#00d4ff");

